"""Research authoring source, deliberately outside runtime skill assets."""
SOURCES = []
CARDS = []

def source(sid, title, url, role, access, supports, limit):
    SOURCES.append(dict(id=sid,title=title,url=url,role=role,access=access,
                        accessed_on="2026-10-09 KST",supports=supports,limits=limit))

def card(cid, title, owner, slot, prop, meaning, boundary, observation, refs, variants):
    """Each variant: explicit directed relation and independently selectable prose."""
    CARDS.append(dict(id=f"SF{cid:03d}",title=title,owner=owner,slot=slot,
                     property_family=prop,meaning_ko=meaning,confusion_boundary=boundary,
                     observation_condition=observation,source_ids=refs.split(),
                     variants=variants,authorship="researcher_derived_optional_realizations",
                     status="research_draft_not_runtime_registered"))

def variant(subject, predicate, obj, text):
    return dict(relation=dict(subject=subject,type=predicate,object=obj),prompt_en=text)

