card(1,"베이식 티와 베이비 티","same T-shirt","wardrobe_style","wardrobe.fit","베이식은 장식 수준, baby tee는 짧고 비교적 가까운 몸판·소매의 판매 형태다.","baby는 착용자 나이가 아니며 크롭 길이·배꼽 노출과 필연적으로 결합하지 않는다.","상체 앞면에서 소매 끝·몸판 밑단·여유를 함께 본다.","S02 S07",[variant("the T-shirt sleeve hem","ends_near","the upper arm","the T-shirt has short fitted sleeves; its compact body ends at the upper hip")])
card(2,"크롭·마이크로 크롭 길이","same top hem relative to torso","garment_detail","wardrobe.length","일반 상의보다 짧은 밑단의 상대 위치이며 micro는 비표준 강화 표현이다.","밑단, 하의 윗선, 배꼽 위치는 세 개의 기준선이다; 노출을 자동 추론하지 않는다.","상의 밑단과 허리 주변이 가려지지 않는 앞면.","S23 S45",[variant("the top hem","ends_above","the trouser waistband","the cropped top ends above the trouser waistband; a narrow band of abdomen separates the two garment edges"),variant("the top hem","ends_at","the lower ribcage","the short top ends at the lower ribcage; a separate high waistband rises close to that hem")])
card(3,"탱크·골지 탱크·캐미솔","same top shoulder connections","garment_detail","wardrobe.structure.strap","민소매 탱크의 어깨 연결과 가는 끈 캐미솔을 구분하고 rib는 별도 표면 축이다.","tank/cami 끈 폭의 판매 경계는 겹친다; 광택·레이스·피부 노출은 별도.","어깨 연결부·암홀·원단 골을 각각 식별.","S07 S43",[variant("the tank shoulder band","connects","the front and back bodice","broad fabric bands join the tank front and back over the shoulders; its armholes have finished edges"),variant("the camisole strap","connects","the front and back upper edges","two narrow straps join the camisole front and back; the light bodice hangs from those straps")])
card(4,"튜브·반도·스트랩리스","same strapless top","garment_detail","wardrobe.structure.strap","수평 몸통 밴드와 어깨 연결 없는 구조, 그리고 몸판 길이를 독립적으로 기술한다.","반도 밴드 형태에 탈착 스트랩이 있는 제품도 있어 bandeau=strapless 완전 동의어는 아니다.","앞·어깨·옆면, 탈착 연결 고리는 별도 가까운 시점.","S12 S43",[variant("the strapless top upper edge","runs_across","the upper torso","the strapless top has a horizontal upper edge across the torso; its continuous bodice extends to the waist")])
card(5,"홀터·하이넥 홀터","same halter top or dress","garment_detail","wardrobe.structure.strap","목 뒤 연결 경로와 앞쪽 덮는 높이를 분리한다.","halter는 깊은 V·백리스·삼각컵·짧은 길이의 동의어가 아니다.","목 뒤 연결까지 보이는 사선 시점; 앞목 높이는 앞면에서.","S22 S43",[variant("the halter front panel","joins_at","the back of the neck","the halter front panel rises to the base of the neck; its upper bands join behind the neck"),variant("the halter straps","join_at","the back of the neck","two bands rise from the open front neckline; they tie together behind the neck")])
card(6,"스카프·반다나 톱","same tied scarf top","wardrobe_style","wardrobe.structure.front_fastener_state","평면 천의 겹침·묶음과 삼각형 밑단이 특징인 하나의 실현 방식이다.","실제 스카프를 묶은 구조와 완성된 패턴 의복을 분리; paisley는 필수 아님.","앞의 삼각 밑단과 실제 묶임 위치를 연결해 본다.","S16 S30",[variant("the scarf corners","tie_at","the back of the same torso","a folded scarf wraps around the torso; its lower corner points downward and its side corners meet in a back knot")])
card(7,"브라톱·브라렛","same short bust-covering top","wardrobe_style","wardrobe.structure","짧은 상의의 컵·밴드·끈 형태와 부드러운 브라렛을 선택형으로 표현한다.","bra top이 스포츠 기능·와이어·란제리 문맥을 모두 요구하지 않는다.","가슴 위 가장자리와 밑가슴 밴드를 볼 수 있어야 한다.","S12 S24 S25",[variant("the short top cups","join","the underbust band","the short top has two fabric cup sections; both join a continuous underbust band")])
card(8,"랩 여밈과 서플리스 목둘레","same crossed front bodice","garment_detail","wardrobe.structure.front_fastener_state","사선 앞판 겹침은 네크라인 관계이고 실제 wrap은 여밈 관계까지 필요하다.","끈 장식이나 V선만으로 풀리는 랩을 확정하지 않는다. pullover mock-wrap과 side-zipper를 별도 변형으로 유지.","겹침의 자유 가장자리와 고정·매듭 양 끝을 확인한다.","S27 S28",[variant("the outer front panel","overlaps","the inner front panel of the same dress","one dress front panel overlaps the other diagonally; its free edge meets a waist tie"),variant("the two front bodice panels","cross_above","the fixed waist seam","two front bodice panels cross into a V neckline; their lower edges join the same fixed waist seam")])
card(9,"타이프런트·타이백","same top closure","garment_detail","wardrobe.structure.front_fastener_state","묶음이 놓인 방향과 실제로 연결하는 패널을 지정한다.","앞 매듭이 복부 틈을 반드시 만들지는 않으며 tie-back이 백리스와 같지는 않다.","매듭·끈 출발점·양 패널 끝을 한 시점에서 본다.","S22 S23",[variant("the two front fabric ends","join_in","a knot on the same top","two front fabric ends meet in a knot; each end remains attached to its own side of the bodice"),variant("the two back straps","join_in","a knot across the same back opening","two back straps meet in a visible knot; their ends connect to the left and right bodice edges")])
card(10,"밀크메이드·피전트","same blouse selected construction","wardrobe_style","wardrobe.structure","연상군을 컵 주변 모음·목둘레 모음·소매 볼륨·자수 등 선택 요소로 해체한다.","milkmaid에 퍼프·면·컵·스퀘어넥을 모두 의무화하지 않는다; peasant도 같은 템플릿 아님.","선택한 주름 출발점과 소매/몸판의 연결이 보이는 상체.","S21 S23",[variant("the blouse bust gathers","converge_toward","the lower bodice seam","small gathers shape the blouse bust above a horizontal seam; flutter sleeves extend from the shoulder openings"),variant("the blouse neckline gathers","radiate_into","the loose front bodice","fine gathers run around the blouse neckline; the loose bodice hangs below the gathered opening")])
card(11,"스모크 톱·셔링·스모킹","same garment gathered area","garment_detail","wardrobe.structure","평행 봉제 줄의 모음과 주름 위 장식 자수를 구분한다.","retail smocked가 실제 탄성 셔링일 수 있다; 늘어남 성능은 정지 사진으로 확정하지 않는다.","봉제 줄 또는 장식 자수가 식별되는 근접면.","S03",[variant("parallel stitch rows","gather","the same blouse waist panel","parallel stitched rows gather the blouse waist panel; small folds repeat between the rows"),variant("decorative crossing stitches","bridge","the gathered folds of the same panel","decorative stitches bridge adjacent gathered folds; the repeated stitching forms a small geometric pattern")])
card(12,"크로셰·크로셰 톱·커버업","same crocheted garment layer","surface_material","wardrobe.material.visible_weave","코바늘 고리·모티프와 조직 틈을 표현하되 의복 역할은 별도로 둔다.","crochet는 섬유 종류가 아니며 촘촘한 crochet도 가능; 모든 crochet가 비치지는 않는다.","원래 저장 해상도에서 고리·틈을 식별; 아래층도 함께 보이는 시점.","S01 S16",[variant("the crochet loops","form","the same top surface","interlinked yarn loops form the top surface; small openings separate the looped motifs")])
card(13,"시어·시어 셔츠·세미시어","same outer fabric and inner layer","surface_material","wardrobe.material.transmission","연속된 원단을 통한 광학 투과를 의복 안쪽 층에 연결한다.","같은 색 속옷은 피부와 다르며 시어를 구멍·나체로 대체하지 않는다.","외곽 원단 경계, 겹수, 아래층의 연속성이 보이는 시점.","S05 S39",[variant("the sheer shirt fabric","transmits_the_outline_of","the opaque camisole underneath","the sheer shirt remains a continuous outer fabric layer; the opaque camisole is visible through it"),variant("the overlapping sheer panels","reduce_visibility_of","the inner garment","the inner garment is visible through a single sheer panel; its outline becomes weaker where two panels overlap")])
card(14,"캠프·쿠반칼라","same shirt collar","garment_detail","wardrobe.neckline","목 주변에 평평하게 펼쳐지는 convertible 칼라와 열린 앞선을 기술한다.","칼라가 tropical print·반소매·특정 국적을 요구하지 않는다.","칼라의 접힌 끝과 앞여밈 연결이 보이는 정면.","S20",[variant("the open shirt collar","lies_flat_against","the same upper chest","the open collar folds flat against the upper chest; its points sit on either side of the front opening")])
card(15,"알로하 셔츠·트로피컬 프린트","same shirt printed surface","wardrobe_style","wardrobe.pattern","열대 식물 등의 무늬 모티프와 셔츠 기본 구조를 분리한다.","모든 camp collar가 Hawaiian은 아니며 착용자 민족·해변 배경은 필수 아님.","큰 잎·꽃의 반복이 원단을 따라 이어지는 시점.","S32 S18",[variant("tropical leaf motifs","repeat_across","the same shirt panels","large tropical leaf motifs repeat across the shirt panels; the print follows the fabric folds")])
card(16,"폴로 칼라와 짧은 플래킷","same polo shirt","garment_detail","wardrobe.neckline","접힌 칼라와 목에서 몸판 중간까지만 내려오는 짧은 단추선.","폴로 경기 장면이나 전체 셔츠형 단추 여밈이 아니다.","칼라와 부분 플래킷 끝이 함께 보이는 정면.","S01 S07",[variant("the button placket","ends_within","the polo front bodice","a folded collar surrounds the polo neckline; a short button placket ends within the front bodice")])
card(17,"베스트·웨이스트코트 단독 상의","same sleeveless vest","wardrobe_style","wardrobe.structure","앞단추·V선·조끼 몸판을 상의로 읽는 착장 방식.","속에 셔츠가 있어야 하는 의무도, 맨몸 단독 착장의 자동 의무도 없다.","소매 없는 연결과 앞여밈, 이너 여부는 실제로 보이는 부분만.","S01 S30",[variant("the vest front edges","meet_at","the central button row","the sleeveless vest fronts meet along a central button row; shaped side panels narrow toward the waist")])
card(18,"크루넥","same top neckline","garment_detail","wardrobe.neckline","목 아래를 비교적 높게 둥글게 감싸는 선.","high neck나 터틀넥 높이·필수 바디콘과 합치지 않는다.","목의 기준점과 원단 윗선이 드러난 앞면.","S43",[variant("the rounded top neckline","sits_near","the base of the neck","the rounded neckline sits near the base of the neck; the front fabric covers the upper chest")])
card(19,"스쿠프·딥 스쿠프","same top neckline","garment_detail","wardrobe.neckline","목 파임의 둥근 곡선과 깊이를 분리하여 기록한다.","U곡선, 넓은 폭, 깊은 파임은 관련 있지만 서로 동일하지 않다.","정면, 가장자리의 연속된 곡선과 내려가는 위치.","S43",[variant("the scoop neckline","curves_below","the collarbones","the neckline forms a broad rounded U; its lowest curve sits below the collarbones")])
card(20,"V와 플런징","same top central neckline","garment_detail","wardrobe.neckline","중앙 V 형상과 깊은 파임을 다른 속성으로 둔다.","plunge의 판매 설명이 V에 치우치더라도 특정 비V의 깊은 파임 문맥을 소거하지 않는다; cleavage 별도.","파임 양쪽 경계와 최저점이 식별되는 앞면.","S43 S24",[variant("the two sloping neckline edges","meet_at","a central front point","two sloping neckline edges meet at a central front point; the point lies below the upper chest")])
card(21,"스퀘어넥","same bodice neckline","garment_detail","wardrobe.neckline","가로 하단과 양쪽 직선에 가까운 측면으로 둘러싼 선.","쇄골 노출은 깊이·폭에 달림; 둥근 sweetheart나 bandeau의 직선만으로 대체 못함.","정면, 모서리가 실제 원단 가장자리여야 함.","S43 S23",[variant("the neckline side edges","join","the horizontal lower neckline edge","near-vertical neckline sides meet a horizontal lower edge; both corners are visible on the same bodice")])
card(22,"스위트하트","same bodice upper edge","garment_detail","wardrobe.neckline","두 윗곡선과 가운데 내려간 접점의 관계.","하트 프린트·가슴골·푸시업과 다른 구조.","컵 윗선 전체와 중앙 접점이 보이는 앞면.","S43",[variant("the two rounded upper edges","meet_at","the central neckline dip","two rounded upper edges meet at a central dip; the same fabric bodice continues below them")])
card(23,"스트레이트어크로스","same top upper edge","garment_detail","wardrobe.neckline","몸통 앞쪽을 수평으로 가로지르는 윗선.","어깨끈·컵 형태·밑단 길이는 별도다.","수평 윗선과 어깨 연결이 확인되는 앞면.","S43 S12",[variant("the straight upper edge","extends_across","the same front bodice","a straight upper edge extends across the front bodice; narrow shoulder straps attach at its outer ends")])
card(24,"보트·바토넥","same top neckline","garment_detail","wardrobe.neckline","얕고 좌우로 넓은 목 파임과 어깨 쪽 끝점.","넓음이 deep scoop이나 어깨 아래로 내려간 off-shoulder와 같지 않다.","양쪽 어깨까지 들어오는 정면.","S43",[variant("the boat neckline","extends_toward","both shoulder tops","the shallow neckline extends toward both shoulder tops; the fabric still covers the outer shoulders")])
card(25,"카울·드레이프","same hanging neckline fabric","garment_detail","wardrobe.material.drape","여분의 원단이 늘어져 생기는 앞목 주름과 중력 방향.","cowl은 단순 U컷·주름 프린트·별도 목걸이가 아니며 깊이는 선택.","드레이프 가장자리와 원단 연속이 읽히는 근접 사선.","S43 S01",[variant("the loose neckline fabric","hangs_between","its two shoulder attachments","loose neckline fabric hangs between its shoulder attachments; curved folds descend across the front")])
card(26,"오프숄더·바르도","same top upper edge and sleeves","garment_detail","wardrobe.coverage.shoulder","윗선이 양쪽 실제 어깨 아래로 내려간 상태.","drop shoulder 봉제선·cold-shoulder 개구부와 분리; 원단을 내린 착용 상태도 별도.","양쪽 어깨와 소매 시작점이 같이 보이는 앞면.","S43",[variant("the upper garment edge","sits_below","both shoulder tops","the upper garment edge sits below both shoulder tops; the sleeves begin around the upper arms")])
card(27,"원숄더·비대칭 목둘레","same bodice shoulder attachment","garment_detail","wardrobe.coverage.shoulder","원숄더는 한 어깨의 연결, asymmetry는 더 넓은 좌우 불균형 범주.","화면 왼쪽과 착용자 왼쪽을 혼동하지 않는다; 모든 비대칭이 원숄더는 아님.","어깨 양쪽과 같은 의복의 대각선을 확인.","S43",[variant("the bodice upper edge","rises_to","the wearer's right shoulder attachment","the bodice rises to the wearer's right shoulder; its opposite upper edge ends below the left shoulder")])
card(28,"콜드숄더","same sleeve shoulder bridge","garment_detail","wardrobe.coverage.shoulder","어깨의 개구부 위로 연결부가 남고 그 아래에 소매가 이어지는 구조.","off-shoulder 전체 이동과 다른 개구부 토폴로지.","어깨의 남은 브리지와 개구부 아래 소매 연결이 보임.","S43 S01",[variant("the shoulder bridge","spans_above","the sleeve shoulder opening","a fabric bridge remains over the shoulder opening; the sleeve continues below the exposed shoulder")])
card(29,"키홀·프런트 컷아웃","same front bodice opening","garment_detail","wardrobe.coverage.opening_location","키홀은 위쪽이 연결된 작은 개구부, front cutout은 위치 범주다.","목 파임의 열린 가장자리·망사 투과·찢김 프린트로 대체하지 않는다.","개구부 둘레의 연속된 경계와 위의 연결부.","S43 S17",[variant("the top neckline band","bridges_above","the enclosed keyhole opening","a small enclosed keyhole opens below the neckline; a fabric band bridges its upper edge")])
card(30,"일루전·누드 일루전","same sheer support panel","garment_detail","wardrobe.material.transmission","얇은 패널이 실제로 연결하는 경계와 피부색에 가까운 색을 별도로 기술한다.","nude는 색·착장·나체 다의어; 같은 피부색의 불투명 원단도 가능.","망사 가장자리·봉제·겹침이 확인되는 해상도; 피부색은 해당 착용자 기준.","S43 S39",[variant("the sheer support panel","connects","the bodice edge to the shoulder seam","a fine sheer panel connects the bodice edge to the shoulder seam; its faint boundary remains visible"),variant("the fabric surface color","resembles","the wearer's local skin tone","the fabric surface is close in color to the wearer's skin; a seam and folded fabric edge establish the garment layer")])
card(31,"슬리브리스·캡 슬리브","same top arm opening","garment_detail","wardrobe.structure.sleeve","소매 없음과 어깨끝만 덮는 짧은 소매의 차이.","슬리브리스는 암홀 깊이·겨드랑이 가시성·노출 면적을 자동 결정하지 않는다.","어깨끝·암홀 경계가 함께 보이는 앞/사선.","S01 S43",[variant("the sleeveless armhole edge","surrounds","the same arm opening","the finished armhole edge surrounds the arm opening; the bodice has no projecting sleeve"),variant("the cap sleeve edge","extends_over","the shoulder tip","a small cap sleeve extends over the shoulder tip; its lower edge ends above the upper arm")])
card(32,"플러터·퍼프 소매","same sleeve volume","garment_detail","wardrobe.structure.sleeve","플러터의 자유 하단 퍼짐과 퍼프의 모음으로 생긴 부피를 구분한다.","겹치는 flutter/puff cap 변형을 허용; 바람·움직임·좁은 허리를 필수화하지 않는다.","부착선·소매 하단과 부피를 동시에 봄.","S21 S23",[variant("the flutter sleeve free edge","flares_away_from","the upper arm","the flutter sleeve has a loose flared lower edge; its fabric hangs away from the upper arm"),variant("the gathered sleeve fabric","bulges_between","its shoulder seam and gathered cuff","the sleeve fabric bulges between the shoulder seam and a gathered cuff; small folds converge at both boundaries")])
