card(90,"부르키니의 층 구성","same covered swim ensemble","wardrobe_style","wardrobe.layers","머리·소매·몸통·다리 덮개와 부착/분리 경로를 선택형으로 기록한다.","3-piece·헐렁함·특정 종교·국적·연령·UPF를 자동 부여하지 않는다.","후드/머리덮개 연결·상의 밑단·바지 경계를 전체 시점에서 본다.","S19",[variant("the swim head covering","connects_to","the long-sleeved upper garment","the head covering connects to the long-sleeved upper garment; separate full-length swim trousers continue below the top")])
card(91,"커버업·카프탄·튜닉·비치 셔츠·로브","same outer garment over swimwear","wardrobe_style","wardrobe.layers","커버업은 용도이며 몸판 길이·앞여밈·소매·밑단이 실제 형태다.","kaftan의 문화 복식 전체를 beach loose dress로 축소하지 않는다; sheer/wet 자동 추가 없음.","겉층 가장자리와 안쪽 수영복이 같은 착용자에게 연결됨.","S16 S19",[variant("the open outer shirt panels","frame","the swimsuit underneath","open outer shirt panels frame the swimsuit underneath; the shirt has its own collar and finished hem"),variant("the loose tunic hem","hangs_over","the separate swim bottom","a loose tunic hem hangs over the separate swim bottom; its broad body falls from the shoulders")])
card(92,"섬유·브랜드·조성","same textile material specification","surface_material","wardrobe.material","cotton/linen은 섬유, rayon/viscose/modal/lyocell은 재생 셀룰로오스 계열, TENCEL은 브랜드; nylon/polyester/elastane은 별도 조성 축이다.","브랜드와 일반 섬유를 합치지 않는다; 같은 섬유가 다양한 weave/knit/finish에 사용됨. 사진은 정확 혼방·브랜드·친환경 성능을 입증하지 못한다.","비시각 명세로 보존; 필요한 표면·처짐·투과만 별도 가시 후보에서 선택.","S05 S08 S09 S10",[])
card(93,"포플린·론·보일·거즈·더블거즈·시어서커","same light fabric structure","surface_material","wardrobe.material.visible_weave","미세하고 비교적 매끈한 원단, 성긴 원단, 겹친 거즈와 반복 puckering을 분리한다.","가벼움=투명함 아님; seersucker의 반복 요철을 무작위 착용 구김이나 shirring 봉제 줄로 대체하지 않는다.","매끈함/구멍/겹수/요철 각각 적절한 근접 해상도; 숨은 double layer는 미확인.","S05 S03",[variant("the seersucker raised bands","alternate_with","flatter woven bands","small raised puckered bands alternate with flatter woven bands; the pattern repeats across the same fabric"),variant("the fine voile layer","transmits","a faint inner garment outline","a fine voile layer hangs in light folds; a faint inner garment outline is visible through the continuous weave")])
card(94,"샴브레이·데님","same woven fabric surface","surface_material","wardrobe.material.visible_weave","평직의 색실 혼합과 데님의 능직 사선 표면을 나눈다.","파란 색 하나로 denim을 확정하지 않으며 chambray를 모든 denim과 동일시하지 않는다.","실 방향이 분해되는 원해상도 근접면.","S06 S05",[variant("the visible diagonal yarn ridges","cross","the denim fabric surface","fine diagonal yarn ridges cross the denim surface; the ridges continue through the fabric folds")])
card(95,"시폰·조젯·오간자","same sheer fabric drape","surface_material","wardrobe.material.drape","가볍게 흐르는 투과면, 잔 크레이프 표면, 얇지만 형태를 지탱하는 부피의 차이를 다룬다.","세 판매명을 전부 동일한 흐르는 silk로 병합하지 않는다; 섬유 조성·정확 weave는 별도.","처짐과 실제 주름 면·비침을 비교할 근접 사선.","S01 S06",[variant("the thin organza folds","hold_away_from","the covered garment underneath","thin translucent folds hold away from the garment underneath; sharp fold edges maintain a light structured volume")])
card(96,"새틴 조직과 광택","same fabric face","surface_material","wardrobe.material","조직 이름과 매끈한 광택의 시각 표현을 나눈다.","satin=실크·젖음·vinyl이 아니며 광택만으로 새틴 조직을 확정하지 않는다.","연속 하이라이트와 접힘 변화; exact weave는 근접 결 증거가 별도로 필요.","S06",[variant("the smooth fabric face","carries","broad highlights along the folds","the smooth fabric face carries broad highlights; the highlights change gently across the soft folds")])
card(97,"저지·리브·테리","same knitted surface","surface_material","wardrobe.material.visible_weave","편직 고리면, 반복 골, 표면 pile loop를 각각 기록한다.","rib의 줄무늬와 인쇄 stripe는 다르고 terry가 반드시 젖은 수건은 아니다.","골·고리가 분해되는 근접 해상도.","S07",[variant("the rib knit raised columns","alternate_with","recessed knitted columns","raised knit columns alternate with recessed columns; the vertical rib texture follows the same top folds"),variant("small pile loops","project_from","the same terry fabric face","small pile loops project from the fabric face; their repeated looped texture remains visible in the light")])
